import{_ as t,o as e,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const c=JSON.parse('{"title":"Getting started with geospatial data","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/geospatial.md","filePath":"getting-started/geospatial.md","lastUpdated":1786379412000}'),s={name:"getting-started/geospatial.md"};function n(l,a,d,r,g,h){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="getting-started-with-geospatial-data" tabindex="-1">Getting started with geospatial data <a class="header-anchor" href="#getting-started-with-geospatial-data" aria-label="Permalink to &quot;Getting started with geospatial data&quot;">​</a></h1><p>NADA catalogs <strong>geographic datasets and data services</strong> using the <strong>ISO 19139</strong> metadata standard.</p><p>Publishing geospatial entries is currently <strong>API-first</strong>:</p><ul><li>Loading ISO 19139 XML through the web UI is not available yet.</li><li>Creating complex geospatial metadata from scratch in the web UI is not available; use a specialized editor (for example GeoNetwork) or generate metadata with R/Python and publish via the API.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Read the full guide and API examples: <a href="/nada-documentation/admin-guide/content/geospatial.html">Adding a geographic dataset</a>.</li><li>Review <a href="/nada-documentation/admin-guide/organize-files.html#geospatial-data">Organize files</a> for a suggested folder layout.</li><li>Ensure you have an administrator API key and <a href="/nada-documentation/admin-guide/api-tools.html">NADAR</a> or PyNADA installed.</li></ol><div class="tip custom-block"><p class="custom-block-title">Recommended order</p><p>If you are new to NADA, complete the <a href="./microdata.html">microdata</a> tutorial first (UI workflow and publishing). Geospatial publishing builds on the same API authentication pattern.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/nada-documentation/admin-guide/core-concepts.html">Core concepts</a> — geospatial vs other types</li><li><a href="/nada-documentation/admin-guide/content/data-api.html">Making data accessible via API</a> — when exposing data through NADA’s data API</li></ul>',9)])])}const u=t(s,[["render",n]]);export{c as __pageData,u as default};
